(()=>{'use strict';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let profiles,loading=false;const ids={'tanod.dev':'tanod','horizonpulse.dev':'horizon','vextorium.com':'vextorium'};
async function activity(p){if(p.sampleOnly&&!p.activityConnected){const el=document.querySelector('[data-new-id="'+p.activityKey+'"]');if(el){el.querySelector('[data-update]').textContent='Payment evidence verified';el.querySelector('[data-coverage]').textContent=p.evidence.length+' operator test payment example'+(p.evidence.length===1?'':'s')+' verified. Full activity totals are not connected in this local preview.';}return;}try{const r=await fetch((p.sampleOnly?'/new-listings/community-activity.php?project=':'/new-listings/activity.php?project=')+(p.activityKey||ids[p.id]));if(!r.ok)throw Error();const d=await r.json();const el=document.querySelector('[data-new-id="'+(p.activityKey||ids[p.id])+'"]');if(!el)return;el.querySelector('[data-count]').textContent=Number(d.transactions).toLocaleString();el.querySelector('[data-wallets]').textContent=Number(d.wallets).toLocaleString();if(el.querySelector('[data-volume]'))el.querySelector('[data-volume]').textContent=Number(d.volumeUSDC).toLocaleString(undefined,{maximumFractionDigits:6});el.querySelector('[data-update]').textContent=d.checkedAt?(d.status==='delayed'?'Update delayed · retained data':d.partial?'History still indexing':'30-day recipient index'):'Index starting · reviewed receipts';const date=d.updatedAt?new Date(d.updatedAt*1000).toLocaleString():null;el.querySelector('[data-coverage]').textContent=(date?'Checked '+date+'. ':'')+Object.entries(d.perNetwork||{}).map(([n,v])=>n+': '+Number(v).toLocaleString()).join(' · ')+'. '+(d.coverage||'Includes operator tests; recipient receipts are not complete platform usage.');}catch{const el=document.querySelector('[data-new-id="'+(p.activityKey||ids[p.id])+'"]');if(el)el.querySelector('[data-update]').textContent='Activity temporarily unavailable';}}
async function mount(){if(location.pathname!=='/'){document.querySelector('#new-reviewed-listings')?.remove();return;}if(document.querySelector('#new-reviewed-listings')||loading)return;const footer=document.querySelector('footer');if(!footer)return;loading=true;try{profiles ||= await fetch('/ai-agents-apps/reviewed-projects.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()});if(location.pathname!=='/')return;const s=document.createElement('section');s.id='new-reviewed-listings';s.setAttribute('aria-label','New project listings');s.innerHTML=`<div class="nl-heading"><div><span class="nl-eyebrow">NEW LISTINGS</span><h2>Discover what’s new</h2><p>Meet the latest projects approved through our public listing review.</p></div><a href="/ai-agents-apps/">Explore agents & apps →</a></div><div class="nl-grid">${profiles.projects.filter(p=>p.sampleOnly&&p.homePlacement!=='main').map(p=>`<article class="nl-card" data-new-id="${(p.activityKey||ids[p.id])}"><div class="nl-top"><img src="${esc(p.logo)}" width="48" height="48" alt="${esc(p.name)} ${p.logoNote?'official account image':'logo'}" title="${esc(p.logoNote||p.name+' logo')}" style="border-radius:50%;object-fit:cover"><div><h3>${esc(p.name)}</h3><span class="nl-reviewed"><i></i> Reviewed listing</span></div><span class="nl-new">NEW</span></div><p class="nl-description">${esc(p.description)}</p><div class="nl-networks">${p.networks.map(n=>`<span>${esc(n)}</span>`).join('')}</div><div class="nl-stats"><div><small>${p.activityShared?'Shared transfers':'Transfers'}</small><strong data-count>—</strong></div><div><small>Sender wallets</small><strong data-wallets>—</strong></div><div><small>Received · USDC</small><strong data-volume>—</strong></div></div><div class="nl-meta"><span>Last 30 days</span><details><summary>Data coverage</summary><p class="nl-status" data-update>Loading activity…</p><p class="nl-coverage" data-coverage>Recipient activity, including operator tests.</p></details></div>${p.activityShared?'<p class="nl-shared">Shared recipient with agent-audit / page-read</p>':''}<a class="nl-profile" href="/ai-agents-apps/?project=${encodeURIComponent(p.id)}">View project <span>↗</span></a></article>`).join('')}</div><p class="nl-footnote">USDC receipts to reviewed payment recipients. A transfer alone does not establish an x402 purchase. Operator tests are included; sender wallets are not individual users. Open a profile for coverage and public evidence.</p>`;footer.before(s);for(const p of profiles.projects)activity(p);}catch{}finally{loading=false;}}
let queued=false;const start=()=>{mount();new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;mount()})}).observe(document.body,{childList:true,subtree:true});setInterval(()=>{if(!document.hidden&&location.pathname==='/'&&profiles)for(const p of profiles.projects)activity(p)},60000);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
(()=>{'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let projects=[],busy=false,queued=false;const data=new Map();
function paint(){
 if(location.pathname!=='/')return;
 const table=document.querySelector('#featured-services tbody');if(!table)return;
 for(const p of projects){
  const id='community-main-'+p.activityKey,profile='/ai-agents-apps/?project='+encodeURIComponent(p.id);let row=document.getElementById(id);
  if(!row){row=document.createElement('tr');row.id=id;row.className='fs-row';row.tabIndex=0;row.setAttribute('role','link');row.setAttribute('aria-label','Open '+p.name);
   row.innerHTML=`<td><div class="fs-server"><img class="fs-logo" src="${esc(p.logo)}" alt="${esc(p.name)} logo" loading="lazy"><div class="fs-server__text"><div class="fs-server__name"><a class="fs-server__title" href="${profile}">${esc(p.name)}</a><em>${p.networks.length} ${p.networks.length===1?'chain':'chains'}</em></div><p>${esc(p.description)}</p><a class="fs-server__url" href="${esc(p.website)}" target="_blank" rel="noopener">${esc(p.id)}</a></div></div></td><td><div class="fs-bars" data-chart role="img" aria-label="Daily USDC recipient transfers"></div></td><td class="fs-num" data-volume>—</td><td class="fs-num" data-count>—</td><td class="fs-num" data-wallets>—</td><td><span class="fs-chain fs-chain--multi">${p.networks.map(n=>`<span class="fs-chain__icon"><img src="/ai-agents-apps/logos/${n.toLowerCase()}.svg" width="16" height="16" alt="${esc(n)}"></span>`).join('')}</span></td><td><a class="fs-try" href="${profile}">Details →</a></td>`;
   row.addEventListener('click',e=>{if(!e.target.closest('a'))location.assign(profile)});row.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target===row)location.assign(profile)});table.append(row);
  }
  const d=data.get(p.activityKey);if(!d)continue;
  const text=(selector,value)=>{const el=row.querySelector(selector);if(el.textContent!==value)el.textContent=value};
  text('[data-volume]','$'+Number(d.volumeUSDC).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:6}));text('[data-count]',Number(d.transactions).toLocaleString());text('[data-wallets]',Number(d.wallets).toLocaleString());
  const note=(p.activityShared?'Shared recipient: agent-audit / page-read. Do not add both rows together. ':'')+'Incoming USDC transfers, including operator tests and deposits; not certified customer purchases. '+(d.status==='delayed'?'Update delayed; retained data. ':'')+(d.partial?'Partial historical coverage. ':'')+'Last checked '+new Date(d.checkedAt*1000).toLocaleString();
  row.title=note;row.querySelector('[data-volume]').title=note;row.querySelector('[data-count]').title=note;
  const chart=row.querySelector('[data-chart]'),key=JSON.stringify(d.history||[]);
  if(chart.dataset.history!==key){const max=Math.max(1,...(d.history||[]).map(x=>x.count));chart.innerHTML=(d.history||[]).map(x=>`<span class="fs-bars__bar" style="height:${x.count/max*100}%;background:#0052ff;opacity:.8" title="${esc(x.date)}: ${x.count} transfers"></span>`).join('');chart.dataset.history=key;}
 }
}
async function refresh(){if(busy)return;busy=true;try{if(!projects.length){const r=await fetch('/ai-agents-apps/reviewed-projects.json',{cache:'no-store'});if(!r.ok)throw Error();projects=(await r.json()).projects.filter(p=>p.homePlacement==='main');}await Promise.all(projects.map(async p=>{try{const r=await fetch('/new-listings/community-activity.php?project='+encodeURIComponent(p.activityKey),{cache:'no-store'});if(!r.ok)throw Error();const d=await r.json();if(Number.isSafeInteger(d.transactions)&&d.transactions>=0&&Number.isSafeInteger(d.wallets)&&d.wallets>=0&&Number.isFinite(Number(d.volumeUSDC)))data.set(p.activityKey,d);}catch{}}));paint();}finally{busy=false}}
function start(){refresh();new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;paint()})}).observe(document.body,{childList:true,subtree:true});setInterval(()=>{if(!document.hidden)refresh()},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
